(()=>{
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),labels={SALES_INV:'Sales Invoice 销售发票',SALES_CN:'Sales Credit Note 客户贷项通知单',DEBIT_NOTE:'Debit Note 客户借项通知单',CUSTOMER_RECEIPT:'Customer Receipt 客户汇款证明'};let dialog,customer='',company='NCT',data=null,pending=null,saving=false,sending=false,timer=null,serial=0,retainedView=null;
function ensureDialog(){if(!dialog){dialog=document.createElement('dialog');dialog.className='master-shipment-dialog customer-document-dialog';document.body.appendChild(dialog);dialog.addEventListener('cancel',event=>{if(saving||pending?.action==='DOCUMENT')event.preventDefault();else pending=null;});}}
function restoreCurrent(entry){if(entry?.ui?.kind!=='DOCUMENT'||entry.request.action!=='DOCUMENT'||entry.ui.company!==entry.request.company||entry.ui.customer!==entry.request.customerId)throw Error('Original file view requires review');
 ensureDialog();company=entry.ui.company;customer=entry.ui.customer;data=entry.ui.data;pending=entry.request;retainedView=entry.ui;saving=false;sending=false;render();
 dialog.querySelector('[data-type]').value=pending.input.type;dialog.querySelector('[data-invoice]').value=pending.input.shipmentId||'';typeChanged();
 for(const key of ['number','date','currency','reason'])dialog.querySelector('[data-'+key+']').value=pending.input[key];dialog.querySelector('[data-amount]').value=(pending.input.amountCents/100).toFixed(2);
 lock();status('Original PDF retained: '+retainedView.file.name+'. Retry the same upload 原 PDF 已保留，请重试同一次上传。');if(!dialog.open)dialog.showModal();
}
function resumeCurrent(entry){if(entry.ui.kind==='DOCUMENT')restoreCurrent(entry);else{window.sourceSalesCurrent.restore(entry);pending=null;dialog.close();}}
function recoveryError(error){saving=false;sending=false;lock();status(error?.message||'Original file save unconfirmed 原文件保存尚未确认');}
function status(value){dialog.querySelector('[data-status]').textContent=value;}
function lock(){dialog.querySelectorAll('input,select,textarea,[data-upload]').forEach(el=>el.disabled=Boolean(pending||saving));dialog.querySelector('[data-close]').disabled=saving||pending?.action==='DOCUMENT';dialog.querySelector('[data-retry]').hidden=!pending||saving;}
function send(action,input){pending={type:'SALES_ROOM_SHIPMENT_REQUEST',customerId:customer,company,action,requestId:crypto.randomUUID(),input:action==='DOCUMENT'&&data?.stockCurrent?JSON.parse(JSON.stringify({...input,stockCurrent:data.stockCurrent})):input};if(pending.input?.stockCurrent){const file=dialog.querySelector('[data-file]').files[0];retainedView={kind:'DOCUMENT',company,customer,data,file:{name:file.name,size:file.size,type:file.type||''}};}transmit();}
function transmit(){if(sending)return;if(pending?.input?.stockCurrent){try{window.sourceSalesCurrent.retain(pending,retainedView);}catch(error){recoveryError(error);return;}}sending=true;saving=true;lock();parent.postMessage(pending,'*');const request=pending,attempt=++serial;clearTimeout(timer);timer=setTimeout(()=>{if(pending===request&&attempt===serial){sending=false;saving=false;lock();status('Not confirmed. Retry the same operation 尚未确认，请重试同一次操作。');}},30000);}
function invoice(){return data?.shipments.find(row=>row.id===dialog.querySelector('[data-invoice]').value);}
function typeChanged(){const isInvoice=dialog.querySelector('[data-type]').value==='SALES_INV';dialog.querySelector('[data-invoice-row]').hidden=!isInvoice;const row=isInvoice?invoice():null;for(const key of ['number','date','currency','amount']){const field=dialog.querySelector('[data-'+key+']');field.readOnly=isInvoice;field.value=row?({number:row.invoice.number,date:row.invoice.date,currency:row.invoice.currency,amount:(row.invoice.amountCents/100).toFixed(2)})[key]:(key==='currency'?'MYR':'');}dialog.querySelector('[data-purpose]').textContent=isInvoice?'Attach the PDF to the Support invoice; amount is not posted twice. 附加到文员已录入的发票，不重复入账。':dialog.querySelector('[data-type]').value==='DEBIT_NOTE'?'Non-stock receivable only 只记录与库存无关的应收款。':'Enter the document amount and explanation 请填写文件金额及说明。';}
function render(){const invoices=(data?.shipments||[]).filter(row=>row.invoice&&!data.customerAccount.entries.some(entry=>entry.id===row.id&&entry.documents.length));dialog.innerHTML='<div class="dialog-header"><div><h2>Sales Documents & Payments 销售文件与收款</h2><small style="color:white">'+esc(data?.customers.find(row=>row.id===customer)?.name||customer)+'</small></div><button data-close>×</button></div><div class="dialog-body"><p data-status role="alert"></p><div class="customer-document-form"><label>Company 公司</label><select data-company><option>NCT</option><option>GHR</option></select><label>Type 文件类型</label><select data-type>'+Object.entries(labels).map(([key,label])=>'<option value="'+key+'">'+label+'</option>').join('')+'</select><div data-invoice-row class="customer-invoice-choice"><label>Invoice 已开销售发票</label><select data-invoice>'+invoices.map(row=>'<option value="'+esc(row.id)+'">'+esc(row.invoice.number)+'</option>').join('')+'</select></div><label>Number 文件号码</label><input data-number maxlength="100"><label>Date 文件日期</label><input data-date type="date"><label>Currency 币种</label><input data-currency maxlength="3"><label>Amount 总额</label><input data-amount inputmode="decimal"><label>PDF 文件</label><input data-file type="file" accept="application/pdf,.pdf"><label>Purpose 用途与说明</label><textarea data-reason rows="2" maxlength="2000"></textarea></div><p data-purpose></p><button data-upload>Upload & Record 上传并记录</button><button data-retry hidden>Retry 重试</button><h3>Recorded Documents 已记录文件</h3>'+(data?.customerAccount.entries||[]).map(row=>'<div class="shipment-record"><b>'+esc(labels[row.type]||row.type)+' · '+esc(row.number)+'</b><small>'+esc(row.currency)+' '+(row.amountCents/100).toFixed(2)+' · '+esc(row.date)+' · '+esc(row.by)+'</small>'+row.documents.map(doc=>'<a href="https://drive.google.com/file/d/'+encodeURIComponent(doc.fileId)+'/view" target="_blank" rel="noopener">View PDF 查看</a>').join(' · ')+(row.documents.length?'':'<small style="color:#bd3d53">● Sales PDF required 等待销售上传文件</small>')+'</div>').join('')+'</div>';dialog.querySelector('[data-company]').value=company;dialog.querySelector('[data-company]').onchange=e=>{if(pending)return;company=e.target.value;data=null;render();send('READ');};dialog.querySelector('[data-type]').onchange=typeChanged;dialog.querySelector('[data-invoice]').onchange=typeChanged;dialog.querySelector('[data-close]').onclick=()=>{if(!saving&&pending?.action!=='DOCUMENT'){pending=null;dialog.close();}};dialog.querySelector('[data-retry]').onclick=transmit;dialog.querySelector('[data-upload]').onclick=upload;typeChanged();}
async function upload(){if(pending||saving||!data)return;const value=key=>dialog.querySelector('[data-'+key+']').value.trim(),file=dialog.querySelector('[data-file]').files[0],amount=value('amount');if(!file||file.size>3*1024*1024||!/^\d+(\.\d{1,2})?$/.test(amount)||!(Number(amount)>0)||!value('number')||!value('date')||!value('reason')){status('Fill all fields and choose a PDF 请填写完整资料并选择 PDF。');return;}saving=true;lock();try{const buffer=await file.arrayBuffer(),bytes=new Uint8Array(buffer);if(new TextDecoder().decode(bytes.slice(0,5))!=='%PDF-')throw Error('Invalid PDF 请选择有效 PDF');let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));const [major,fraction='']=amount.split('.'),amountCents=Number(major)*100+Number(fraction.padEnd(2,'0'));send('DOCUMENT',{action:'DOCUMENT',version:data.accountVersion,customerId:customer,type:value('type'),shipmentId:value('type')==='SALES_INV'?invoice()?.id:'',number:value('number'),date:value('date'),currency:value('currency').toUpperCase(),amountCents,reason:value('reason'),base64:btoa(binary)});}catch(error){saving=false;lock();status(error.message);}}
window.sourceSalesCurrent.register('DOCUMENT',restoreCurrent);
window.addEventListener('beforeunload',event=>{if(pending?.input?.stockCurrent){event.preventDefault();event.returnValue='';}});
window.customerSalesDocuments={open(id){if(saving||pending?.action==='DOCUMENT')return;ensureDialog();customer=id;data=null;pending=null;render();dialog.showModal();send('READ');}};
window.addEventListener('message',event=>{const m=event.data||{};if(event.source!==parent||m.type!=='SALES_ROOM_SHIPMENT_RESULT'||m.requestId!==pending?.requestId||m.company!==company)return;clearTimeout(timer);serial++;sending=false;saving=false;
 if(pending.action==='READ'&&!m.ok){const original=pending;window.sourceSalesCurrent.recover(company,customer).then(entry=>{if(pending!==original)return;if(entry)resumeCurrent(entry);else recoveryError(Error(m.error||'Read unconfirmed 读取尚未确认'));}).catch(error=>{if(pending===original)recoveryError(error);});return;}
 if(pending.input?.stockCurrent&&m.ok){const result=m.result;if(result?.ok===false&&result.pending===true&&result.requestId===pending.requestId&&['BEFORE','APPLY','VERIFY'].includes(result.phase)&&Number.isSafeInteger(result.completedCount)&&Number.isSafeInteger(result.totalRecords)&&result.totalRecords>0&&result.completedCount>=0&&result.completedCount<=result.totalRecords){
  saving=true;sending=true;lock();status('Saving 保存中… '+result.completedCount+' / '+result.totalRecords);const original=pending,attempt=serial;timer=setTimeout(()=>{if(pending===original&&serial===attempt){sending=false;transmit();}},250);return;}
  if(result?.ok!==true||result.requestId!==pending.requestId||!Number.isSafeInteger(result.stockGeneration)||result.stockGeneration<=pending.input.stockCurrent.stockGeneration){recoveryError(Error('Original file save unconfirmed. Retry the same upload 原文件保存尚未确认，请重试同一次上传。'));return;}}
 if(!m.ok||m.result?.ok===false){const error=m.error||m.result.error||'Upload not confirmed 上传尚未确认';if(!pending.input?.stockCurrent&&(pending.action==='READ'||/changed|Enter |already|not authorized|must match|Select a valid|Select a PDF/.test(error)))pending=null;lock();status(error);return;}if(pending.action==='READ'&&m.result?.stockCurrent!==undefined){const original=pending;try{if(window.sourceSalesCurrent.checkRead(company,customer,m.result.stockCurrent,entry=>{if(pending===original)resumeCurrent(entry);},error=>{if(pending===original)recoveryError(error);}))return;}catch(error){recoveryError(error);return;}}
 if(pending.input?.stockCurrent){try{window.sourceSalesCurrent.finish(pending,m.result);}catch(error){recoveryError(error);return;}}const action=pending.action;pending=null;retainedView=null;if(action==='READ'){data=m.result;render();}else send('READ');});
})();
